solution:
use xiom.io;

use xiom.string;
use xiom.convert;
fn sqrt(x: Float64) -> Float64
  requires: x >= 0.0;
{
  return x / 2.0;
}

fn withdraw(balance: Int, amount: Int) -> Int
  requires: amount > 0;
  requires: amount <= balance;
{
  return balance - amount;
}

fn main() -> Int {
  let s = sqrt(25.0);
  io.println(convert.float_to_string(s));
  let b = withdraw(200, 50);
  io.println(to_string(b));
  return 0;
}
